"""U230 — RESTART sweep with BOTH gates built into the generator. Only mechanisms whose statement
is FALSE for a generic coprime triple a+b=c (so the proof must use perfect-power structure AND the
equation) are admitted. 7 objects x 7 uses-of-the-equation x 6 constraints = 294 cells."""
import itertools,json,sys
sys.path.insert(0,'code'); import jev
OBJ=["the multiplicative order of C modulo every prime power dividing A, jointly across all such primes",
 "the ideal (A^x, B^y) in Z[zeta_n] for n = lcm(x,y,z) and its class in the ray class group",
 "the Z-algebra generated by the three power maps restricted to the solution triple",
 "the pair of simultaneous Pell-like relations obtained by writing C^z - A^x = B^y and C^z - B^y = A^x",
 "the two-variable binary form F(U,V) whose value at (A^(x/d), B^(y/d)) is C^z for d = gcd(x,y)",
 "a Frey curve whose coefficients involve ALL THREE of A^x, B^y, C^z symmetrically (not a two-term Frey curve)",
 "the Galois action on the set of z-th roots of A^x + B^y inside a fixed algebraic closure"]
USE=["the equation forces C^z = A^x mod B^y, giving an exact congruence between two perfect powers",
 "the equation forces gcd(C^z - A^x, C^z - B^y) = 1 when the bases are pairwise coprime",
 "the equation makes C^z - A^x itself a perfect y-th power, a strong constraint absent for generic triples",
 "the equation plus positivity pins C^z into the window (max(A^x,B^y), 2*max(A^x,B^y))",
 "the equation makes the triple a rational point on the surface U + V = W with U,V,W on power subvarieties",
 "the equation gives three independent perfect-power conditions at every prime of ABC simultaneously",
 "the equation makes A^x/C^z and B^y/C^z a pair of S-units summing to 1"]
CONS=["the statement must be FALSE for a generic coprime triple a+b=c with non-power terms",
 "the statement must fail for the Z[i] identity (-2+i)^3+(-2-i)^3=(1+i)^4",
 "the proof must not reduce to abc, Baker bounds, a congruence sieve, or a bounded search",
 "it must not fix any base or restrict the exponents to a finite list",
 "it must be checkable exactly on the ten Fermat-Catalan solutions within an hour",
 "it must not be a two-term Frey curve for one signature at a time"]
CTX=("Beal. TWO GATES now in force. Gate 1 (Fermat-Catalan blindness): a condition holding on all ten exponent-2 "
 "solutions carries no Beal content. Gate 2 (new, C094): a condition whose PROOF does not use the equation "
 "A^x+B^y=C^z is the exponent hypothesis in disguise, however it scores on gate 1. Survey lists as failed: bounded "
 "computation/sieves, one-signature modular method, elementary congruences, abc/Baker.")
Q={"passes_gate2":jev.noul("Would the proof of a statement built from this cell NECESSARILY use the equation A^x+B^y=C^z, so that the statement is false for a generic coprime triple with non-power terms?",true="necessarily uses the equation",false="would not"),
 "dead_cat":jev.noul("Does it fall into a survey-dead category (bounded computation, congruence sieve, one-signature Frey curve, abc/Baker)?",true="dead category",false="not dead"),
 "testable":jev.noul("Is there an exact computation on known data that would discriminate it within an hour?",true="testable now",false="not testable now")}
cells=list(itertools.product(OBJ,USE,CONS))
rs=jev.ask_many([{"context":CTX,"object":o,"use_of_equation":u,"constraint":c} for o,u,c in cells],Q,concurrency=16)
rows=[]
for (o,u,c),r in zip(cells,rs):
    if 'answers' not in r: continue
    a={k:round(v['noul'],2) for k,v in r['answers'].items()}
    rows.append((round(a['passes_gate2']*(1-a['dead_cat'])*a['testable'],3),a,o,u,c))
rows.sort(key=lambda r:-r[0])
json.dump({"status":"HYPOTHESIS_ONLY","rows":rows},open('research/pool/evidence/gate2_generator_U230.json','w'),indent=1)
print(len(rows),"cells")
for s,a,o,u,c in rows[:8]: print(s,a,"|",o[:52],"|",u[:52])
